package io.fireflysoftware.core.product.web.config.definition.lifecycle;

import static org.junit.jupiter.api.Assertions.*;
import io.fireflysoftware.core.product.core.services.definition.InsuranceQuotePurposeReferenceResolver;
import java.lang.reflect.*;
import java.util.*;
import org.fireflyframework.security.rs.ResourceServerProperties;
import org.fireflyframework.security.spi.*;
import reactor.core.publisher.Mono;
import org.junit.jupiter.api.Test;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.core.env.MapPropertySource;
import org.springframework.beans.factory.NoSuchBeanDefinitionException;

/** Annotation/DI/credential boundary only; no database, listener, authentication or owner success fixture. */
class ProductDefinitionTermPcDefaultOffTest {
    Class<?> type(String name){try{return Class.forName("io.fireflysoftware.core.product.web.config.definition.lifecycle."+name);}catch(ClassNotFoundException missing){throw new AssertionError("Default-off owner wiring missing: "+name,missing);}}
    Object instance(String name){try{return type(name).getConstructor().newInstance();}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}
    void set(Object value,String property,Object argument){try{value.getClass().getMethod("set"+property,argument instanceof Boolean?boolean.class:String.class).invoke(value,argument);}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}
    @Test void absentFlagsRegisterNeitherRuntimeAndRequireNoCredentials(){for(String prefix:new String[]{"TermPcInsurance","InsuranceQuotePurpose"}){try(var context=new AnnotationConfigApplicationContext()){context.register(type(prefix+"Configuration"));context.refresh();assertEquals(0,context.getBeanNamesForType(type(prefix+"Runtime")).length);}}}
    @Test void explicitFalseAlsoRegistersNoRuntime(){for(var item:Map.of("TermPcInsurance","product.definitions.term-pc.enabled","InsuranceQuotePurpose","product.definitions.insurance-quote-read.enabled").entrySet()){try(var context=new AnnotationConfigApplicationContext()){context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("source-control",Map.of(item.getValue(),"false")));context.register(type(item.getKey()+"Configuration"));context.refresh();assertEquals(0,context.getBeanNamesForType(type(item.getKey()+"Runtime")).length);}}}
    @Test void propertiesDefaultDisabledAndPasswordsAreNotRendered(){for(String name:new String[]{"TermPcInsuranceProperties","InsuranceQuotePurposeReadProperties"}){var props=instance(name);String marker=UUID.randomUUID().toString();try{assertEquals(false,props.getClass().getMethod("isEnabled").invoke(props));if(name.startsWith("Insurance"))set(props,"Password",marker);assertFalse(props.toString().contains(marker));}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}}
    @Test void enabledPurposeRequiresActualReferenceResolverBean(){try(var context=new AnnotationConfigApplicationContext()){context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("source-control",Map.of("product.definitions.insurance-quote-read.enabled","true")));context.register(type("InsuranceQuotePurposeConfiguration"));var error=assertThrows(RuntimeException.class,context::refresh);boolean exact=false;for(Throwable at=error;at!=null;at=at.getCause())if(at instanceof NoSuchBeanDefinitionException missing && missing.getResolvableType().resolve()==InsuranceQuotePurposeReferenceResolver.class)exact=true;assertTrue(exact,"Enabled owner purpose must require the genuine current-reference resolver, without an unavailable/success fallback bean");}}
    @Test void allNewControllersUseExplicitDefaultOffAndExistingBearerScheme(){for(String name:new String[]{"TermPcInsuranceLifecycleController","TermPcInsuranceReadController","InsuranceQuotePurposeController"}){try{var c=Class.forName("io.fireflysoftware.core.product.web.controllers."+name);var condition=c.getAnnotation(ConditionalOnProperty.class);assertNotNull(condition);assertFalse(condition.matchIfMissing());assertEquals("true",condition.havingValue());var security=c.getAnnotation(io.swagger.v3.oas.annotations.security.SecurityRequirement.class);assertNotNull(security);assertEquals("productDefinitionBearer",security.name());}catch(ClassNotFoundException missing){throw new AssertionError("Default-off controller missing",missing);}}}
    Map<Class<?>,Object> arguments(){var args=new HashMap<Class<?>,Object>();var commands=new ProductDefinitionCommandProperties();commands.setEnabled(true);args.put(ProductDefinitionCommandProperties.class,commands);args.put(ProductDefinitionPublicationReadProperties.class,new ProductDefinitionPublicationReadProperties());args.put(ResourceServerProperties.class,new ResourceServerProperties());args.put(type("TermPcInsuranceProperties"),instance("TermPcInsuranceProperties"));args.put(type("InsuranceQuotePurposeReadProperties"),instance("InsuranceQuotePurposeReadProperties"));args.put(SecurityContextPort.class,(SecurityContextPort)()->Mono.empty());args.put(PolicyDecisionPort.class,(PolicyDecisionPort)(p,a,r,c)->Mono.error(new IllegalStateException("No source decision")));return args;}
    Throwable factoryFailure(String name,Map<Class<?>,Object> args){var config=instance(name);var method=Arrays.stream(config.getClass().getDeclaredMethods()).filter(m->m.isAnnotationPresent(org.springframework.context.annotation.Bean.class)).findFirst().orElseThrow();try{method.invoke(config,Arrays.stream(method.getParameterTypes()).map(args::get).toArray());throw new AssertionError("Invalid feature inputs unexpectedly constructed a runtime");}catch(InvocationTargetException expected){return expected.getCause();}catch(ReflectiveOperationException failure){throw new AssertionError(failure);}}
    void status(Throwable error,String message){assertInstanceOf(IllegalStateException.class,error);assertEquals(message,error.getMessage());assertNull(error.getCause());}
    @Test void enabledFactoriesRejectMissingCredentialsBeforeOwnerFactoryOrPoolAccess(){for(String name:new String[]{"TermPcInsuranceConfiguration","InsuranceQuotePurposeConfiguration"})status(factoryFailure(name,arguments()),"PRODUCT_INSURANCE_CREDENTIALS_REQUIRED");}
    @Test void enabledFactoriesRequireExplicitExistingCommandConfiguration(){for(String name:new String[]{"TermPcInsuranceConfiguration","InsuranceQuotePurposeConfiguration"}){var args=arguments();((ProductDefinitionCommandProperties)args.get(ProductDefinitionCommandProperties.class)).setEnabled(false);status(factoryFailure(name,args),"PRODUCT_COMMAND_CONFIGURATION_REQUIRED");}}
    @Test void purposeReadIdentityCannotReuseCommandCredentials(){var args=arguments();var commands=(ProductDefinitionCommandProperties)args.get(ProductDefinitionCommandProperties.class);commands.setUsername("command-source");var properties=args.get(type("InsuranceQuotePurposeReadProperties"));set(properties,"Username","command-source");set(properties,"Password",UUID.randomUUID().toString());status(factoryFailure("InsuranceQuotePurposeConfiguration",args),"PRODUCT_INSURANCE_DISTINCT_IDENTITY_REQUIRED");}
    @Test void purposeReadRequiresIssuerAudienceAndRequiredSignedTenantProjection(){var args=arguments();((ProductDefinitionCommandProperties)args.get(ProductDefinitionCommandProperties.class)).setUsername("command-source");var properties=args.get(type("InsuranceQuotePurposeReadProperties"));set(properties,"Username","purpose-source");set(properties,"Password",UUID.randomUUID().toString());status(factoryFailure("InsuranceQuotePurposeConfiguration",args),"PRODUCT_INSURANCE_CALLER_TRUST_REQUIRED");}
    @Test void termPcCannotSelectLegacyPolicyProfileFromConfiguration(){var args=arguments();var commands=(ProductDefinitionCommandProperties)args.get(ProductDefinitionCommandProperties.class);commands.setUsername("command-source");commands.setPassword(UUID.randomUUID().toString());((ResourceServerProperties)args.get(ResourceServerProperties.class)).setIssuer("https://issuer.example");set(args.get(type("TermPcInsuranceProperties")),"PolicyProfile","product-definition-human-staff-v1");status(factoryFailure("TermPcInsuranceConfiguration",args),"PRODUCT_TERM_PC_POLICY_TRUST_REQUIRED");}
    @Test void runtimeHoldersDoNotBecomeAmbiguousLegacyServiceBeans(){for(var name:new String[]{"TermPcInsuranceRuntime","InsuranceQuotePurposeRuntime"})for(var port:new Class<?>[]{io.fireflysoftware.core.product.core.services.definition.ProductDefinitionLifecycleService.class,io.fireflysoftware.core.product.core.services.definition.ProductDefinitionCostReadService.class,io.fireflysoftware.core.product.core.services.definition.ProductDefinitionReviewReadService.class,io.fireflysoftware.core.product.core.services.definition.InsuranceQuotePurposeService.class})assertFalse(port.isAssignableFrom(type(name)));}

    @Test void purposeReadIdentityCannotReuseBroaderPublicationReader(){var args=arguments();((ProductDefinitionCommandProperties)args.get(ProductDefinitionCommandProperties.class)).setUsername("command-source");((ProductDefinitionPublicationReadProperties)args.get(ProductDefinitionPublicationReadProperties.class)).setUsername("publication-source");var properties=args.get(type("InsuranceQuotePurposeReadProperties"));set(properties,"Username","publication-source");set(properties,"Password",UUID.randomUUID().toString());status(factoryFailure("InsuranceQuotePurposeConfiguration",args),"PRODUCT_INSURANCE_DISTINCT_IDENTITY_REQUIRED");}

}
